import{_ as d,o,c,a2 as t}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"构建与打包（开发者参考）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/build.md","filePath":"zh/dev/build.md"}'),a={name:"zh/dev/build.md"};function s(n,e,i,r,l,p){return o(),c("div",null,[...e[0]||(e[0]=[t(`<h1 id="构建与打包-开发者参考" tabindex="-1">构建与打包（开发者参考） <a class="header-anchor" href="#构建与打包-开发者参考" aria-label="Permalink to &quot;构建与打包（开发者参考）&quot;">​</a></h1><p>构建系统的开发者视角。用户级指南见 <a href="./../root/BUILDING.html">BUILDING.md</a>；工具链设置见 <a href="./environment.html">environment.md</a>。以下事实来自顶层 <code>Makefile</code>（740 行）、<code>tools/build.sh</code> 与各组件的 <code>.mk</code> 文件。</p><h2 id="_1-你实际会用到的目标" tabindex="-1">1. 你实际会用到的目标 <a class="header-anchor" href="#_1-你实际会用到的目标" aria-label="Permalink to &quot;1. 你实际会用到的目标&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -j$(nproc) kernel     # fast inner loop: ELF only (default goal)</span></span>
<span class="line"><span>make iso                   # + bootable dual-firmware ISO</span></span>
<span class="line"><span>make all                   # userprogs + kernel + ISO + src zip + OTA</span></span>
<span class="line"><span>make userprogs             # regenerate the embedded program registry</span></span>
<span class="line"><span>make userprogs-check       # staleness gate (wired into make dist)</span></span>
<span class="line"><span>make test                  # host unit tests (no QEMU needed)</span></span>
<span class="line"><span>make run-bios | run-uefi | run-bios-gui | run-uefi-gui</span></span>
<span class="line"><span>make run-bios-persist      # no -snapshot: /etc edits persist in etc.img</span></span>
<span class="line"><span>make shot-bios | shot-uefi # VNC screendump -&gt; PNG</span></span>
<span class="line"><span>make reproducible-check    # two clean builds -&gt; byte-identical ELF</span></span>
<span class="line"><span>make defconfig | menuconfig</span></span>
<span class="line"><span>make cache-stats | cache-clear</span></span>
<span class="line"><span>make l0-i18n | api-docs</span></span>
<span class="line"><span>make ocire-kernel | ocbl-bios | ocbl-efi | ocse-elf   # sibling kernels</span></span>
<span class="line"><span>make ARCH=arm64 | ARCH=riscv                            # bring-up shells</span></span>
<span class="line"><span>make clean</span></span></code></pre></div><h2 id="_2-makefile-变量-含隐藏变量" tabindex="-1">2. Makefile 变量（含隐藏变量） <a class="header-anchor" href="#_2-makefile-变量-含隐藏变量" aria-label="Permalink to &quot;2. Makefile 变量（含隐藏变量）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>默认值 / 推导</th><th>含义</th></tr></thead><tbody><tr><td><code>OC_TOOLS</code></td><td><code>/usr</code></td><td>迁移（dpkg -x）树的工具链根；由 <code>tools/build.sh</code> 探测 <code>/usr</code>、<code>$HOME/tools/grub</code> 自动检测</td></tr><tr><td><code>OVMF_FD</code></td><td><code>$(OC_TOOLS)/share/ovmf/OVMF.fd</code></td><td><code>run-uefi*</code> 目标的 UEFI 固件</td></tr><tr><td><code>QEMU_DATADIR</code></td><td><code>$(OC_TOOLS)/share/qemu</code></td><td>QEMU <code>-L</code> 路径</td></tr><tr><td><code>SEABIOS_DIR</code></td><td><code>$(OC_TOOLS)/share/seabios</code></td><td>BIOS 固件</td></tr><tr><td><code>OC_RELEASE_VERSION</code></td><td>固定字面量（如 <code>3.0.0-NAK</code>）</td><td>内核横幅 / uname / 更新检查字符串；用 <code>?=</code>，命令行覆盖优先 —— E2E 更新测试以如 <code>make OC_RELEASE_VERSION=WP-10c-test1</code> 构建</td></tr><tr><td><code>OC_KERNEL_BUILD_OFFSET</code></td><td><code>21</code></td><td>在 <code>git rev-list --count HEAD</code> 之上的对齐偏移（保持数字 OTA 比较在已发布 id 278/321/414/416 之上单调）</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td><code>expr git rev-list --count HEAD + 21</code></td><td>单调构建 id（BUG-0347）；可用 <code>make OC_KERNEL_BUILD=42</code> 覆盖</td></tr><tr><td><code>OC_CACHE_DIR</code></td><td><code>$(HOME)/.cache/opencube-cc</code></td><td>编译缓存根（<code>oc_cc.sh</code>）；<code>OC_CACHE_OFF</code> 绕过</td></tr><tr><td><code>CONFIG_NVME</code> / <code>CONFIG_AHCI</code> / <code>CONFIG_VIRTIO_BLK</code></td><td><code>y</code>（存在 <code>.config</code> 时取自其中）</td><td>硬件画像开关；<code>=n</code> 会把该驱动的 <code>.c</code> 从 <code>KERNEL_C</code> 过滤掉并将其 init 打桩</td></tr><tr><td><code>ARCH</code></td><td><code>x86_64</code>（亦支持 <code>arm64</code>、<code>riscv</code>）</td><td>分发到对应架构的 <code>build.mk</code>，而不是整段 x86_64 主体</td></tr><tr><td><code>CC</code> / <code>LD</code> / <code>NASM</code> / <code>QEMU</code></td><td><code>gcc</code> / <code>ld</code> / <code>nasm</code> / <code>qemu-system-x86_64</code></td><td>工具选择（按 PATH 解析）</td></tr><tr><td><code>KERNEL_DIRS</code></td><td>kernel + arch + services + drivers 通配</td><td>源码通配根</td></tr><tr><td><code>KERNEL_INC</code></td><td>每个 <code>KERNEL_DIRS</code> 的 <code>-I</code> + <code>tools</code> + <code>services/*/interface</code> + <code>kernel/generated</code> + <code>include</code></td><td>多 <code>-I</code> 纯基名 include 策略</td></tr><tr><td><code>LDFLAGS</code></td><td><code>-n -nostdlib -T ocos/kernel/arch/x86_64/linker.ld -z max-page-size=0x1000 -z noexecstack</code></td><td>内核链接</td></tr><tr><td><code>ETC_IMG</code></td><td><code>build/etc.img</code></td><td>32 MiB FAT32 <code>/etc</code> 卷（mformat + mcopy <code>etc/opencube.conf</code>）</td></tr><tr><td><code>SRC_ZIP</code> / <code>OTA_PKG</code></td><td><code>dist/OpenCubeOS-src-&lt;ver&gt;.zip</code> / <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code></td><td>发布产物</td></tr></tbody></table><p>工具所认的环境变量：<code>OC_TOOLS</code>、 <code>OC_RELEASE_VERSION</code>/<code>OC_KERNEL_BUILD</code>（make 覆盖）、 <code>OC_CACHE_DIR</code>/<code>OC_CACHE_OFF</code>、<code>ARCH</code>/<code>CROSS</code>、<code>JOBS</code> （build.sh，默认 nproc）、<code>OVMF_FD</code>/<code>QEMU_DATADIR</code>/ <code>SEABIOS_DIR</code>、<code>OC_PROMPT</code>（qemu_runner 提示符正则， 默认 <code>(?:ush&gt;|oc&gt;)\\s</code>）、<code>OC_CMD_TIMEOUT</code>（默认 300）、 <code>OC_USB_SERIAL_ECHO</code>、<code>OC_ETC_IMG</code>（供宿主密钥快速路径 使用的预播种 /etc）、<code>LD_LIBRARY_PATH</code>（迁移的 QEMU 库）、 <code>SOURCE_DATE_EPOCH</code>。</p><h2 id="_3-cflags-与-d-宏表" tabindex="-1">3. CFLAGS 与 -D 宏表 <a class="header-anchor" href="#_3-cflags-与-d-宏表" aria-label="Permalink to &quot;3. CFLAGS 与 -D 宏表&quot;">​</a></h2><p>内核 CFLAGS（x86_64）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-ffreestanding -fno-stack-protector -fno-pie -fno-pic</span></span>
<span class="line"><span>-mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel</span></span>
<span class="line"><span>-fno-asynchronous-unwind-tables -Wall -Wextra -Werror</span></span>
<span class="line"><span>-O2 -g -std=gnu11 $(KERNEL_INC)</span></span>
<span class="line"><span>-DOC_RELEASE_VERSION=\\&quot;$(OC_RELEASE_VERSION)\\&quot;</span></span>
<span class="line"><span>-DOC_KERNEL_BUILD=$(OC_KERNEL_BUILD)</span></span>
<span class="line"><span>-MMD -MP</span></span></code></pre></div><p>零警告门禁：每个组件（kernel、OCIRE、OCBL、OCSE、 agent）都开 <code>-Wall -Wextra -Werror</code> —— 这是本项目的 &quot;lint&quot;。</p><p>构建期 <code>-D</code> 宏：</p><table tabindex="0"><thead><tr><th>宏</th><th>定义处</th><th>启用什么</th></tr></thead><tbody><tr><td><code>OC_RELEASE_VERSION</code></td><td>kernel/OCSE/arch CFLAGS（字符串）</td><td>横幅、uname、更新检查版本</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td>kernel/OCSE/arch CFLAGS（数字）</td><td>参与数字比较的构建 id</td></tr><tr><td><code>OCBL_RELEASE</code>、<code>OCBL_BUILD</code></td><td>ocbl.mk 两种风味</td><td>OCBL 横幅/版本</td></tr><tr><td><code>OCBL_FLAVOR_BIOS</code></td><td>ocbl.mk BIOS 对象</td><td>选择 int-13h/VGA/E820/VBE 后端</td></tr><tr><td><code>OCBL_FLAVOR_UEFI</code></td><td>ocbl.mk EFI 对象</td><td>同一契约的 EFI 后端</td></tr><tr><td><code>OCSE_RELEASE</code>、<code>OCSE_BUILD</code></td><td>ocse.mk</td><td>OCSE 横幅（<code>&lt;ver&gt;-ocse</code>）</td></tr><tr><td><code>OCBL_ELTORITO</code> / <code>OCBL_MBR</code></td><td><code>ocbl_bios_stage1.asm</code> 上的 NASM <code>-D</code></td><td>汇编哪种 512 字节 stage1 风味</td></tr><tr><td><code>OC_CONFIG_NVME</code> / <code>OC_CONFIG_AHCI</code> / <code>OC_CONFIG_VIRTIO_BLK</code></td><td>生成的 <code>config_gen.h</code>（0/1）</td><td>硬件画像；<code>0</code> 还会把 <code>driver_block_&lt;x&gt;_init()</code> 打桩</td></tr><tr><td><code>OC_VERSION_STAMP</code></td><td>生成的 <code>version_gen.h</code></td><td>触发重编译的字符串</td></tr><tr><td><code>OCIRE_STAMP</code></td><td>生成的 <code>ocire_version_gen.h</code></td><td>OCIRE 重编译触发器</td></tr><tr><td><code>RSA_DEBUG</code></td><td><code>svc_crypto_rsa.c</code> 内源码局部 <code>#ifdef</code></td><td>RSA 路径的调试打印 —— 编辑该文件顶部的 <code>#define</code> 启用</td></tr></tbody></table><p>构建文件中<strong>没有</strong> <code>NAP_SANITIZE</code>、<code>DEBUG</code> 或 <code>OC_DEBUG</code> 构建宏 —— 调试行为按工具区分（宿主测试用各自的 gcc 命令行编译；若干在本地使用 ASAN）。</p><h2 id="_4-0x400000-窗口与逐文件优化覆盖" tabindex="-1">4. 0x400000 窗口与逐文件优化覆盖 <a class="header-anchor" href="#_4-0x400000-窗口与逐文件优化覆盖" aria-label="Permalink to &quot;4. 0x400000 窗口与逐文件优化覆盖&quot;">​</a></h2><p>内核镜像必须结束在 <strong>0x400000</strong> 以下 —— 由 <code>linker.ld</code> 中的链接期 ASSERT 强制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ASSERT(__end_of_kernel &lt;= 0x400000, &quot;kernel image grew past the 0x400000 identity-window boundary - move large buffers to kmalloc&quot;)</span></span></code></pre></div><p>原因：用户地址空间把<em>虚拟</em>窗口 0x400000-0x600000 重映射 到空 PT（P3-1 安全修复），因此内核在用户 CR3 上运行时 永远不能解引用在该<em>物理</em>区间内发出的 PMM 帧；PMM 永久 保留这 512 帧，而镜像结束于 0x400000 以下让恒等窗口 保持无歧义。所有大对象（1024 项 klog 环、32 连接 TCP 表、 管道、崩溃转储缓冲区）都因此放在内核堆上。</p><p><strong>9 个逐文件 <code>-Os</code> 覆盖</strong>（通则是 <code>-O2</code>；这些文件把 <code>-O2</code> 过滤掉改用 <code>-Os</code>）：</p><ul><li><code>drv_net_wireless.c</code>、<code>drv_net_iwlwifi.c</code>、 <code>drv_net_rtlwifi.c</code>、<code>drv_net_ath.c</code>、<code>drv_net_brcm.c</code> （无线家族）</li><li><code>drv_storage_sdhci.c</code></li><li><code>drv_misc_mjpeg.c</code>、<code>drv_misc_camera.c</code>、 <code>drv_misc_camera_uvc.c</code></li></ul><p>原因：实测 <code>-O2</code> 下超出约 8 KiB —— 覆盖让镜像留在 窗口内（链接器 ASSERT 是字节精确的）；相机一组对 代码生成还额外敏感。</p><p><strong>1 个逐文件 <code>-O0</code> 覆盖</strong>：</p><ul><li><code>drv_bus_acpi_aml.c</code> —— AML 解释器：<code>-O2</code> 代码生成 曾让 <code>kfree</code> 因野指针崩溃；<code>-O0</code> 能干净解析 QEMU 的 现场 DSDT。（AML 是对生成代码的解释 —— 优化会改变 解释器所依赖的生命期。）</li></ul><p>历史注记：NAK 清理期间刻意删除了两条针对根级 <code>tui/</code> 目录的死 <code>-Os</code> 规则 —— 路径迁移逐文件覆盖规则时照此 办理。</p><h2 id="_5-两阶段链接与-cmp-守护的生成器" tabindex="-1">5. 两阶段链接与 cmp 守护的生成器 <a class="header-anchor" href="#_5-两阶段链接与-cmp-守护的生成器" aria-label="Permalink to &quot;5. 两阶段链接与 cmp 守护的生成器&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KERNEL_OBJ + grub_boot_stub.o --ld--&gt; build/opencube_base.elf (+strip)</span></span>
<span class="line"><span>embed_grub.py --&gt; generated/grub_boot_data.c --&gt; grub_boot_data.o</span></span>
<span class="line"><span>KERNEL_OBJ + grub_boot_data.o --ld--&gt; build/opencube.elf (+strip)</span></span></code></pre></div><ul><li><strong>阶段 1</strong> 以 <code>core_boot_grubstub.c</code> 中的强零长度 <code>grub_boot_img</code> / <code>grub_core_img</code> 符号链接，因此内核 在真实启动数据存在之前就能链接。</li><li><strong>阶段 2</strong>：<code>tools/embed_grub.py</code> 以磁盘上配置所需的 模块（biosdisk、part_msdos/gpt、fat、multiboot2、 search_fs_file、normal、configfile、echo、serial、 test、ls）运行 <code>grub-mkimage</code>，把 512 字节 boot.img + 164,355 字节 core.img 输出为 C 数组；阶段 2 链接用 真实数据替换桩符号。<code>install</code>/<code>abdisk</code>/<code>grub-install</code> 就是这样写出零外部文件的可启动磁盘的。</li><li><strong>cmp 守护</strong>：<code>version_gen.h</code> 与 <code>config_gen.h</code> 是 FORCE 运行的生成器，其输出只在内容有差异时才重写 （<code>cmp</code> 守护）。<code>version_gen.h</code> 携带 <code>#define OC_VERSION_STAMP &quot;&lt;ver&gt; build &lt;build&gt;&quot;</code>， 使 <code>-D OC_RELEASE_VERSION</code> 对 <code>-MMD -MP</code> 依赖图可见 （WP-10-tui-qa 修复：增量构建曾在新代码上保留旧横幅）。 <code>config_gen.h</code> 是每个对象的 order-only 前置，因此它 在任何编译之前就存在。同一幂等发射（字节比较）模式 守护着 <code>userprogs_data.h</code>、<code>core_lib_i18n_data.c</code> 和 IME 词组表。</li></ul><h2 id="_6-应用内嵌链" tabindex="-1">6. 应用内嵌链 <a class="header-anchor" href="#_6-应用内嵌链" aria-label="Permalink to &quot;6. 应用内嵌链&quot;">​</a></h2><p><code>make userprogs</code>（<code>make all</code> 的一部分，<code>make dist</code> 中由 <code>userprogs-check</code> 守护）运行 <code>tools/gen_userprogs.py</code>： 发现每个 <code>ocos/l1apps/&lt;name&gt;/</code> 目录 + 扁平遗留程序， 逐个 freestanding 编译（仅 <code>-I ocos/interface</code>），按镜像 模式链接（ET_EXEC @0x400000 / PIE + PT_INTERP / ld_so @0x10000000），把每个 ELF gzip 成 <code>userprog_gz_&lt;sym&gt;[]</code>（每应用一条 gzip 流；ush 保持 原始），并输出 <code>ocos/kernel/userprogs_data.h</code>（blob + <code>OC_USERPROGS[]</code> + <code>OC_USERPROGS_COUNT</code>）。没有手工 注册这回事；一个新目录就是一条新命令。过期集合包括 <code>*.c</code>、<code>*.asm</code>、<code>ocos/interface/*.h</code> 与每个 <code>i18n/*.json</code>（WP06g2 提示清扫在一次现场捕获后补上了 json）。</p><h2 id="_7-编译缓存" tabindex="-1">7. 编译缓存 <a class="header-anchor" href="#_7-编译缓存" aria-label="Permalink to &quot;7. 编译缓存&quot;">​</a></h2><p><code>tools/oc_cc.sh</code> 用内容寻址缓存包裹每条编译规则： 键 = SHA-256(编译器身份 + 完整标志集 + 源内容哈希 + 来自 <code>-MM</code> 的每个头依赖的内容哈希)。热对象与冷对象 字节一致，因此 <code>make reproducible-check</code> 保持有效； 过期的缓存条目不可能存在（任何头编辑都会改变键）。 用 <code>make cache-stats</code> / <code>make cache-clear</code> 管理。</p><h2 id="_8-打包确定性-g13" tabindex="-1">8. 打包确定性（G13） <a class="header-anchor" href="#_8-打包确定性-g13" aria-label="Permalink to &quot;8. 打包确定性（G13）&quot;">​</a></h2><ul><li><strong>ELF</strong>：树中没有 <code>__DATE__</code>/<code>__TIME__</code>/ <code>__TIMESTAMP__</code>；固定链接顺序（通配展开）； <code>strip --strip-debug</code>；导出时尊重 <code>SOURCE_DATE_EPOCH</code>。</li><li><strong>SRC zip</strong>（<code>make src-zip</code>）：从 tag <code>v&lt;ver&gt;</code> 执行 <code>git archive</code>（回退 HEAD 并大声警告）—— 树序、提交 mtime、索引权限。</li><li><strong>OTA</strong>（<code>make ota</code>）：内核 + 清单（清单携带按归档 顺序拼接的成员体之上的载荷 sha256）；先强制刷新 ISO （针对旧 ISO + 新 OTA 的 v2.0.0 修复）。</li><li><strong>FAT 镜像</strong>：<code>tools/fat_zero_dates.py</code> 把日期/时间 字段清零（mformat/mcopy 会打上墙上时钟）。</li><li><strong>ISO</strong>：xorriso 钉住卷日期/节点时间/GPT GUID/ESP 序列号；<code>tools/iso_zero_ctime.py</code> 把 Rock Ridge TF ctime/atime 重写为 epoch。</li><li><strong>OCOS.TAR</strong>（安装载荷）：ustar、零 mtime、uid/gid 0、 排序、NUL 填充头。</li><li><code>make reproducible-check</code>：两次干净构建，字节比较 ELF， 有差异即退出码 1。</li></ul><h2 id="_9-多配置与交叉构建" tabindex="-1">9. 多配置与交叉构建 <a class="header-anchor" href="#_9-多配置与交叉构建" aria-label="Permalink to &quot;9. 多配置与交叉构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # .config with everything on</span></span>
<span class="line"><span>make menuconfig         # interactive (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_NVME=n iso  # hardware profile: NVMe off</span></span>
<span class="line"><span>make CONFIG_AHCI=n CONFIG_VIRTIO_BLK=n iso</span></span>
<span class="line"><span>make ARCH=arm64         # PL011 bring-up shell ELF (aarch64-linux-gnu-)</span></span>
<span class="line"><span>make ARCH=riscv         # NS16550A bring-up shell ELF (riscv64-linux-gnu-)</span></span></code></pre></div><p>被禁用的配置把驱动 init 调用编译为空操作桩，绝不删除 代码。注意 <code>tools/oc_menuconfig.sh</code> 的菜单文本仍在宣传 已移除的 <code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> 开关（过时 —— Makefile 只消费 NVME/AHCI/VIRTIO_BLK；CJK 流水线是 无条件的）。</p><h2 id="_10-可脚本化-api-与发布自动化" tabindex="-1">10. 可脚本化 API 与发布自动化 <a class="header-anchor" href="#_10-可脚本化-api-与发布自动化" aria-label="Permalink to &quot;10. 可脚本化 API 与发布自动化&quot;">​</a></h2><p><code>tools/build.sh</code> 兼作函数库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/build.sh</span></span>
<span class="line"><span>build_all; build_iso; build_src; build_ota</span></span>
<span class="line"><span>config_load; config_save; config_get; cache_lookup</span></span>
<span class="line"><span>cross_compile; cross_toolchain_setup</span></span>
<span class="line"><span>tools/build.sh api-selftest     # verifies the spec&#39;d interfaces</span></span></code></pre></div><p>发布 SOP 组合这些函数而不是解析 make 输出 —— 见 <a href="./../release/process.html">../release/process.md</a> 与 <code>tools/build_release.sh &lt;ver&gt; [--deep]</code>（干净 <code>make all</code> -&gt; <code>reproducible-check</code> -&gt; BIOS+UEFI 横幅 门禁 -&gt; 可选深度门禁 -&gt; 文档/网站再生成；打印三个 SHA256；拒绝已存在的 tag 或错误的 git 身份）。</p>`,40)])])}const g=d(a,[["render",s]]);export{h as __pageData,g as default};
